// -------- Helpers --------
function toISO(raw) {
  if (raw == null) return null;

  // String: DD-MM-YYYY o DD/MM/YYYY
  if (typeof raw === 'string') {
    const s = raw.trim();
    const m1 = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
    if (m1) {
      const d = m1[1].padStart(2, '0');
      const mo = m1[2].padStart(2, '0');
      const y = m1[3];
      return `${y}-${mo}-${d}`; // YYYY-MM-DD
    }
    // String: YYYY-MM-DD
    const m2 = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m2) return s;

    // Intento genérico
    const t = new Date(s);
    if (!isNaN(t)) return formatISOFromLocal(t);
    return null;
  }

  // Objeto Date
  if (raw instanceof Date && !isNaN(raw)) {
    return formatISOFromLocal(raw);
  }

  // Número (serial de Google Sheets/Excel)
  if (typeof raw === 'number' && isFinite(raw)) {
    // Base Excel: 1899-12-30 (en UTC)
    const base = new Date(Date.UTC(1899, 11, 30));
    const ms = raw * 86400000;
    const d = new Date(base.getTime() + ms);
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
  }

  return null;
}

function formatISOFromLocal(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function formatDDMMYYYY(d) {
  return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
}

