const salida = [];
const hoy = new Date();
// arrancar desde mañana, con hora normalizada
let cur = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() + 1);

while (salida.length < 5) {
  const iso = formatISOFromLocal(cur);
  const esDomingo = cur.getDay() === 0;
  const estaBloqueada = bloqueadasISO.has(iso);

  if (!esDomingo && !estaBloqueada) {
    salida.push({ json: { fecha_valida: formatDDMMYYYY(cur), fecha_iso: iso } });
  }

  // siguiente día
  cur.setDate(cur.getDate() + 1);
}

return salida;

